return $input.all().map((item, index) => {
  const event = item.json;
  const payload = event.payload;

  const errors = [];

  if (!payload || typeof payload !== "object") {
    errors.push("Missing canonical payload");
  }

  const customer = payload?.customer ?? {};
  const inquiry = payload?.inquiry ?? {};

  const email = String(
    customer.email ?? ""
  ).trim().toLowerCase();

  const name = String(
    customer.name ?? ""
  ).trim();

  const service = String(
    inquiry.service ?? ""
  ).trim();

  if (name.length < 2) {
    errors.push("Customer name is invalid");
  }

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.push("Customer email is invalid");
  }

  if (!service) {
    errors.push("Service is missing");
  }

  const testForceRetry =
    payload?.metadata?.test_force_retry === true;

  let processingStatus = "ready";
  let errorMessage = "";

  if (errors.length > 0) {
    processingStatus = "rejected";
    errorMessage = errors.join("; ");
  } else if (testForceRetry) {
    processingStatus = "failed";
    errorMessage = "Simulated transient failure";
  }

  return {
    json: {
      database_event_id: event.id,
      claim_token: event.claim_token,
      attempt_count: event.attempt_count,

      source: event.source,
      source_event_id: event.source_event_id,

      processing_status: processingStatus,
      error_message: errorMessage,

      customer: {
        name,
        email,
        phone: customer.phone ?? "",
        company: customer.company ?? ""
      },

      inquiry: {
        service,
        budget: inquiry.budget ?? null,
        message: inquiry.message ?? ""
      }
    },
    pairedItem: { item: index }
  };
});
